mapper.select:
SELECT id, video_title AS videoTitle, video_id AS videoId, video_description AS videoDescription, module_category AS moduleCategory, view_count AS viewCount, like_count AS likeCount, author, publish_time AS publishTime, content_status AS contentStatus FROM edu_video_asset
AND DATE(publish_time) >= #{queryDTO.publishStartTime}
AND DATE(publish_time) <= #{queryDTO.publishEndTime}
AND video_title LIKE CONCAT('%', #{queryDTO.videoTitle}, '%')
AND author LIKE CONCAT('%', #{queryDTO.author}, '%')
AND module_category = #{queryDTO.moduleCategory}
AND content_status = #{queryDTO.contentStatus}
ORDER BY id DESC
